export function Permission({
  permissionName = "{{permissionName}}",
  actionLabel = "{{actionLabel}}",
  granted = {{granted}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <code style={{ display: "block", fontFamily: "ui-monospace, monospace", fontSize: 11, background: "#24143012", padding: "8px 10px", borderRadius: 6, marginBottom: 14 }}>{permissionName}: {String(granted)}</code>
      <button type="button" disabled={!granted}
        style={{ border: "none", padding: "10px 18px", borderRadius: 8, color: "#FAF7F2", fontWeight: 600, fontSize: 13, cursor: granted ? "pointer" : "not-allowed", width: "100%", background: accent, opacity: granted ? 1 : .35 }}>{actionLabel}</button>
      {!granted && <p style={{ margin: "8px 0 0", fontSize: 10, color: "#24143099" }}>Blocked &mdash; this user lacks {permissionName}.</p>}
    </div>
  );
}
